package com.nexachat.feature.group;

import android.os.Bundle;
import android.view.LayoutInflater;
import android.view.View;
import android.view.ViewGroup;
import androidx.annotation.NonNull; import androidx.annotation.Nullable; import androidx.fragment.app.Fragment; import androidx.lifecycle.ViewModelProvider; import androidx.navigation.Navigation; import androidx.recyclerview.widget.LinearLayoutManager;
import com.nexachat.R; import com.nexachat.data.GroupMember; import com.nexachat.databinding.FragmentGroupDetailBinding; import com.nexachat.feature.group.adapter.GroupMemberAdapter; import dagger.hilt.android.AndroidEntryPoint;

/** Shows group membership and administrative actions. */
@AndroidEntryPoint public final class GroupDetailFragment extends Fragment {
    private FragmentGroupDetailBinding binding; private GroupDetailViewModel viewModel;
    @Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){binding=FragmentGroupDetailBinding.inflate(i,c,false);return binding.getRoot();}
    @Override public void onViewCreated(@NonNull View view,@Nullable Bundle state){ viewModel=new ViewModelProvider(this).get(GroupDetailViewModel.class); GroupMemberAdapter adapter=new GroupMemberAdapter(new GroupMemberAdapter.Listener(){public void onMemberClick(@NonNull String id){} public void onRemoveMember(@NonNull String id){for(GroupMember member:viewModel.getUiState().getValue().getMembers())if(member.getUserId().equals(id)){viewModel.requestRemoveMember(member);new com.google.android.material.dialog.MaterialAlertDialogBuilder(requireContext()).setMessage(getString(R.string.group_remove_member_confirm,member.getDisplayName())).setNegativeButton(android.R.string.cancel,(d,w)->viewModel.dismissRemoveMember()).setPositiveButton(R.string.action_remove_member,(d,w)->viewModel.confirmRemoveMember()).show();break;}}}); binding.memberList.setLayoutManager(new LinearLayoutManager(requireContext())); binding.memberList.setAdapter(adapter); binding.toolbar.setNavigationOnClickListener(v->Navigation.findNavController(v).navigateUp()); GroupDetailUiState ui=viewModel.getUiState().getValue(); binding.groupTitle.setText(ui.getTitle()); adapter.submitList(ui.getMembers()); binding.groupAvatar.setAvatarUrl(ui.getGroupAvatar()); binding.groupAvatar.setOnClickListener(v->chooseAvatar()); binding.groupTitle.setOnClickListener(v->rename()); binding.membersHeader.setTitle(getString(R.string.group_detail_title)); binding.detailColumn.setOnLongClickListener(v->{showActions();return true;}); }
    private void chooseAvatar(){ androidx.activity.result.ActivityResultLauncher<String> picker=registerForActivityResult(new androidx.activity.result.contract.ActivityResultContracts.GetContent(),uri->{if(uri!=null)viewModel.setGroupAvatar(uri);}); picker.launch("image/*"); }
    private void rename(){android.widget.EditText input=new android.widget.EditText(requireContext());input.setText(viewModel.getUiState().getValue().getTitle());viewModel.openRename();new com.google.android.material.dialog.MaterialAlertDialogBuilder(requireContext()).setTitle(R.string.action_rename_group).setView(input).setNegativeButton(android.R.string.cancel,(d,w)->viewModel.dismissRename()).setPositiveButton(R.string.action_save,(d,w)->{viewModel.onRenameInputChange(input.getText().toString());viewModel.confirmRename();}).show();}
    private void showActions(){new com.google.android.material.dialog.MaterialAlertDialogBuilder(requireContext()).setItems(new CharSequence[]{getString(R.string.action_add_member),getString(R.string.action_rename_group),getString(R.string.action_leave_group)},(d,w)->{if(w==0)viewModel.openAddMember();else if(w==1)rename();else{viewModel.requestLeave();new com.google.android.material.dialog.MaterialAlertDialogBuilder(requireContext()).setMessage(R.string.group_leave_confirm).setNegativeButton(android.R.string.cancel,(x,y)->viewModel.dismissLeave()).setPositiveButton(R.string.action_leave_group,(x,y)->viewModel.confirmLeave()).show();}}).show();}
    @Override public void onDestroyView(){super.onDestroyView();binding=null;}
}
